{
  "case_id": "xsu_sg_006_work_history_information",
  "criteria": {
    "c01_overall_legal_correctness": {"label": "not_met", "reason": "Svaret nævner ikke de centrale oplysninger: arbejdstimer og indkomst fra Skattestyrelsen, ansøgerens egne oplysninger i ansøgningen og arbejde under studiet. Det tilføjer i stedet uddannelse/kompetencer, arbejdsmarkedsmuligheder og en vurdering af, om indkomsten er 'tilstrækkelig at leve for'. Det er ikke dækket af kilderne og forskubber vurderingen af erhvervsevne."},
    "c02_required_elements_complete": {"label": "not_met", "reason": "Ingen af de fire kritiske elementer er med. Skattestyrelsen og arbejdstimer/indkomst nævnes ikke. Ansøgerens egne oplysninger om tidligere arbejdsforhold nævnes ikke eksplicit. Betydningen af arbejdsophør (andre forhold end funktionsnedsættelsen, ingen forværring) og arbejde under studiet mangler. Kun 'arbejdshistorik' og 'indkomst' er nævnt helt generelt."},
    "c03_direct_relevance": {"label": "not_met", "reason": "Svaret er en generisk liste. Den dækker ikke, hvilke arbejds- og indkomstoplysninger der bruges, og hvor de kommer fra. Flere punkter, fx uddannelse og arbejdsmarkedsmuligheder, handler ikke om arbejds- og indkomstoplysninger."},
    "c04_source_traceability": {"label": "not_met", "reason": "Svaret angiver ingen identificerbar kilde (lov, bekendtgørelse eller vejledning)."},
    "c05_source_validity": {"label": "not_assessable", "reason": "Ingen kilde er angivet, så gyldigheden kan ikke vurderes."},
    "c06_claim_source_support": {"label": "not_assessable", "reason": "Ingen kilde er angivet, så støtten til påstandene kan ikke vurderes."},
    "c07_no_unsupported_legal_additions": {"label": "not_met", "reason": "Svaret tilføjer uunderbyggede elementer: at uddannelse og kompetencer, arbejdsmarkedsmuligheder og om indkomsten er 'tilstrækkelig at leve for' bruges i vurderingen. Det har ikke støtte i de frosne kilder. Det angiver også, at oplysningerne bruges til at fastsætte 'hvor meget' tillæg, hvilket kilderne ikke understøtter."},
    "c08_qualifications_and_exceptions": {"label": "not_met", "reason": "Det kvalificerende forbehold mangler. Svaret nævner ikke, at tidligere arbejde især er relevant, når ophøret skyldtes andre forhold og funktionsnedsættelsen ikke er forværret. Det siger kun generelt, at vurderingen er individuel og varierer. Det erstatter ikke de forbehold, rubrikken kræver."},
    "c09_reasoning_coherence": {"label": "met", "reason": "Svaret er internt sammenhængende: det opregner oplysninger og konkluderer, at de indgår i en individuel vurdering. Der er ingen indre modsigelser, selv om indholdet er forkert og ufuldstændigt."},
    "c10_legal_modality_precision": {"label": "met", "reason": "Svaret bruger ikke absolutte formuleringer, som ændrer betydningen. Det understreger, at vurderingen er individuel, og at oplysningerne kan variere. Det gør ikke skøn eller undtagelser til absolutte regler."}
  },
  "xhaile_coverage": {
    "A18": {"label": "no", "reason": "Svaret nævner ikke, at oplysninger om arbejdstimer og indkomst indhentes fra Skattestyrelsen. Det nævner kun 'indkomst' helt generelt."},
    "A19": {"label": "partial", "reason": "Svaret nævner 'arbejdshistorik', men ikke at ansøgerens egne oplysninger om tidligere arbejdsforhold angives i ansøgningen og inddrages."},
    "A20": {"label": "no", "reason": "Svaret dækker ikke, at erhvervsarbejde før ansøgningen kan indgå, navnlig ved arbejdsophør af andre grunde uden forværring. Det nævner heller ikke, at arbejde under studiet indgår."}
  },
  "overall_notes": "Svaret er generisk og uden kildehenvisning. Det mangler alle kritiske elementer (Skattestyrelsen, ansøgerens egne oplysninger, betydningen af arbejdsophør, arbejde under studiet) og tilføjer uunderbyggede faktorer. Kun C09 og C10 er opfyldt."
}

